import pickle
from phoenix.fgen.instruction3 import InstructionGroup
import warnings

# pylint: disable=too-many-arguments


class AbstractRoutine:
    """An abstract routine does not specify input or output data types,
    therefore all instructions remain based on keys.
    """

    def __init__(
        self,
        name: str,
        *,
        itype,
        instruction_group=None,
    ):
        self._name = name
        if instruction_group is None:
            warnings.warn(f"Routine {name} has empty instruction group")
            instruction_group = InstructionGroup([])
        self.instruction_group = instruction_group
        self.localized_instructions = InstructionGroup([])
        self._dependencies: list[Routine] = []
        self._itype = itype
        self._ready = False

    def __len__(self):
        return len(self.instruction_group)

    @property
    def itype(self):
        """write-protected access to itype"""
        return self._itype

    @property
    def instructions(self):
        """generator through all instructions.
        Forward the call into the instruction into the top level instruction
        group
        """
        yield from self.instruction_group.instructions

    @classmethod
    def get_filename(cls, name):
        """standard way to get a filename. Handle path and naming convention"""
        return f"routine_{name}_data.pckl"

    @classmethod
    def from_file(cls, name):
        """get from file"""
        filename = cls.get_filename(name)
        with open(filename, "rb") as f:
            routine = pickle.load(f)
        return routine

    def to_file(self):
        """write to file"""
        filename = self.get_filename(self.name)
        with open(filename, "wb") as f:
            pickle.dump(self, f)

    # @staticmethod
